@id("close-workorder-main-with-recent-person-approval")
permit (principal, action == Drupe::Action::"MaintData___close_workorder", resource)
when { context.input.site_id == "MAIN" }
when temporal {
  formerly within 1h Drupe::Action::"Tamsora___get_approval"::response{
    eventResource: resource,
    input.site_id: context.input.site_id,
    input.wonum: context.input.wonum,
    output.decision: Drupe::Tamsora___get_approval_Output_decision::"ACCEPTED",
    output.approver_kind: Drupe::Tamsora___get_approval_Output_approver_kind::"PERSON"
  }
};

// The approval lookups must be permitted themselves, or their responses are never recorded.
@id("allow-approval-lookup-tamsora")
permit (principal, action == Drupe::Action::"Tamsora___get_approval", resource);

@id("allow-approval-lookup-vantry")
